{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique como a forma das células animais e vegetais pode influenciar suas funções.",
      "resposta_esperada": "A forma irregular das células animais permite maior flexibilidade e adaptação a diferentes funções, enquanto a forma fixa das células vegetais proporciona suporte estrutural e resistência."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de como a presença da parede celular nas células vegetais pode ser vantajosa em um ambiente com muita água.",
      "resposta_esperada": "A parede celular ajuda a evitar a ruptura das células vegetais quando há excesso de água, mantendo a integridade celular e permitindo que a planta cresça saudável."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a função da membrana plasmática nas células animais e vegetais, considerando a presença da parede celular nas vegetais.",
      "resposta_esperada": "Enquanto a membrana plasmática nas células animais é responsável por regular a entrada e saída de substâncias, nas células vegetais, a presença da parede celular fornece suporte adicional, permitindo que a membrana plasmática tenha um papel mais focado na troca de materiais."
    }
  ]
}

