{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Quais são as principais funções do tecido epitelial no corpo humano?",
      "resposta_esperada": "O tecido epitelial tem como principais funções o revestimento de superfícies externas e internas do corpo, além de atuar na proteção, absorção e secreção de substâncias."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Como a falta de vascularização do tecido epitelial pode impactar sua função no organismo?",
      "resposta_esperada": "A falta de vascularização impede a troca direta de nutrientes e oxigênio com o sangue, fazendo com que o tecido epitelial dependa da difusão de substâncias de tecidos adjacentes para se manter saudável."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as características do tecido epitelial com as de outros tipos de tecidos, como o tecido muscular. Quais diferenças são mais significativas?",
      "resposta_esperada": "As principais diferenças incluem que o tecido epitelial é formado por células justapostas com pouca substância intercelular e não possui vascularização, enquanto o tecido muscular possui células mais espaçadas, ricas em vascularização e especializadas para a contração."
    }
  ]
}

{
