{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique o que são características hereditárias e como elas se relacionam com a genética.",
      "resposta_esperada": "Características hereditárias são traços que são passados de pais para filhos através dos genes. A genética estuda como essas características são transmitidas e expressas nas gerações."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de uma característica hereditária e explique como ela pode ser transmitida de uma geração para outra.",
      "resposta_esperada": "Um exemplo de característica hereditária é a cor dos olhos. Se um dos pais tem olhos azuis e o outro tem olhos castanhos, a cor dos olhos dos filhos pode ser influenciada pelos genes que cada pai transmite."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a transmissão de características hereditárias em organismos diferentes, como plantas e animais, e discorra sobre as semelhanças e diferenças.",
      "resposta_esperada": "Tanto em plantas quanto em animais, a transmissão de características hereditárias ocorre através de genes. No entanto, as plantas podem ter características como a altura influenciadas por fatores ambientais de forma mais significativa do que os animais, que geralmente têm uma herança mais direta de características genéticas."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Quais são os principais órgãos sexuais internos do homem e qual é a sua importância para a reprodução?",
      "resposta_esperada": "Os principais órgãos sexuais internos do homem incluem os testículos, epidídimos, ductos deferentes, próstata e uretra. Eles são importantes para a produção, nutrição e transporte dos espermatozoides durante a reprodução."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva como os espermatozoides se movem desde a produção até a ejaculação, mencionando os órgãos envolvidos nesse processo.",
      "resposta_esperada": "Os espermatozoides são produzidos nos testículos, passam para o epidídimo onde amadurecem, e depois seguem pelo ducto deferente, onde se misturam com fluidos da vesícula seminal e próstata antes de serem ejaculado pela uretra."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as funções da próstata e das glândulas bulbouretrais no aparelho reprodutor masculino.",
      "resposta_esperada": "A próstata produz um líquido que nutre os espermatozoides e facilita a sua mobilidade, enquanto as glândulas bulbouretrais secretam um líquido que limpa a uretra antes da passagem do sêmen, preparando o canal para a ejaculação."
    }
  ]
}

{
